import click
from click.testing import CliRunner
r = CliRunner()
def show(name, cmd, args=[], dm=None):
    res = r.invoke(cmd, args, default_map=dm)
    print(f"{name}: exit={res.exit_code} out={res.output!r} exc={res.exception!r}")

@click.group()
@click.option("--flag", is_flag=True)
def g(flag):
    click.echo(f"gflag={flag}")
@g.command()
@click.option("--flag", is_flag=True)
def sub(flag):
    click.echo(f"subflag={flag}")
show("group flag dm", g, [], {"flag": True})
show("group+sub dm", g, ["sub"], {"flag": True, "sub": {"flag": True}})

@click.command()
@click.option("--flag/--no-flag", default=False)
def c(flag):
    click.echo(f"flag={flag}")
for v in [True, False, "1", "0", "true", "false", "yes", "no", "on", "off"]:
    show(f"pair dm={v!r}", c, [], {"flag": v})

@click.command()
@click.option("--flag", is_flag=True, default=False)
def c2(flag):
    click.echo(f"flag={flag}")
for v in [True, False, "1", "0", "true", "false"]:
    show(f"flag dm={v!r}", c2, [], {"flag": v})

@click.command()
@click.option("--upper", "t", flag_value="upper", default="lower")
@click.option("--lower", "t", flag_value="lower")
def c3(t):
    click.echo(f"t={t}")
show("nonbool flag dm None", c3, [], {"t": None})
show("nonbool flag dm 'upper'", c3, [], {"t": "upper"})

@click.command()
@click.option("--flag", is_flag=True, default=True)
def c4(flag):
    click.echo(f"flag={flag}")
show("dm None default True", c4, [], {"flag": None})
